export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;
    const corsHeaders = {
      'Access-Control-Allow-Origin': request.headers.get('Origin') || '*',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, Authorization, apikey, x-client-info, accept, origin',
      'Access-Control-Allow-Credentials': 'true',
      'Access-Control-Max-Age': '86400',
    };

    if (request.method === 'OPTIONS') {
      return new Response(null, { 
        status: 204, 
        headers: corsHeaders 
      });
    }

    const json = (data, status = 200) => new Response(JSON.stringify(data), {
      status, headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });

    const sbFetch = async (endpoint, options = {}) => {
      const res = await fetch(`${env.SUPABASE_URL}/rest/v1/${endpoint}`, {
        ...options,
        headers: {
          'apikey': env.BREZEL_SECRET,
          'Authorization': `Bearer ${env.BREZEL_SECRET}`,
          'Content-Type': 'application/json',
          'Prefer': 'return=representation',
          ...options.headers
        }
      });
      return res.json();
    };

    const tgSend = async (token, text) => {
      await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ chat_id: env.MY_CHAT_ID, text, parse_mode: 'HTML' })
      });
    };

    try {
      // 1. ВЕБХУК ДЛЯ ТЕЛЕГРАМА (Твои ответы)
      if (path === '/webhook' && request.method === 'POST') {
        const update = await request.json();
        
        if (update.message && update.message.reply_to_message && update.message.text) {
            const replyToText = update.message.reply_to_message.text;
            const match = replyToText.match(/\(ID: ([^)]+)\)/);
            
            if (match) {
                const sessionId = match[1].trim();
                await sbFetch('support_messages', {
                    method: 'POST',
                    body: JSON.stringify({
                        session_id: sessionId,
                        sender: 'admin',
                        text: update.message.text
                    })
                });
            }
        }
        return json({ ok: true });
      }

      // 2. ЗАЯВКИ (LEADS)
      if (path === '/api/lead' && request.method === 'POST') {
        const { name, phone, turnstileToken } = await request.json();

        if (env.TURNSTILE_SECRET && turnstileToken !== '1x0000000000000000000000000000000AA') {
          const verifyRes = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: `secret=${env.TURNSTILE_SECRET}&response=${turnstileToken}`
          });
          const verifyData = await verifyRes.json();
          if (!verifyData.success) return json({ error: 'Вы робот!' }, 400);
        }

        const text = `🔥 <b>Новая заявка!</b>\n\n👤 Имя: ${name}\n📞 Телефон: ${phone}`;
        ctx.waitUntil(tgSend(env.CLIENT_BOT_TOKEN, text));
        return json({ success: true });
      }

      // 3. ОФОРМЛЕНИЕ ЗАКАЗА (ORDER)
      if (path === '/api/order' && request.method === 'POST') {
        const { items, total, userName } = await request.json();
        
        if (!Array.isArray(items) || items.length === 0) return json({ error: 'Пустой заказ' }, 400);
        if (total > 100000) return json({ error: 'Слишком большая сумма' }, 400);

        const itemsList = items.map(i => `- ${i.name} (${i.qty} шт.) — ${i.price * i.qty} ₽`).join('\n');
        const text = `📦 <b>Новый заказ!</b>\n\n👤 Клиент: ${userName}\n\n🛒 Товары:\n${itemsList}\n\n💰 <b>Итого: ${total} ₽</b>`;

        ctx.waitUntil(tgSend(env.ADMIN_BOT_TOKEN, text));
        return json({ success: true });
      }

      // 4. ЧАТ С ИИ (ДОКТОР БРЕЗЕЛЬ)
      if (path === '/api/gigachat' && request.method === 'POST') {
        const { message, sessionId, history } = await request.json();
        if (!message || message.length > 1000) return json({ reply: 'Слишком длинное сообщение.' }, 400);

        const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
        const limitKey = `limit_${ip}_${sessionId}`;
        let msgCount = parseInt(await env.MESSAGES_KV.get(limitKey)) || 0;
        const authHeader = request.headers.get('Authorization');

        // Лимит для незалогиненных
        if (msgCount >= 5 && !authHeader) {
          return json({ reply: '🚫 Вы исчерпали лимит (5 сообщений). Зарегистрируйтесь, чтобы продолжить общение.' });
        }

        // Защита от спама/хакеров
        const badWords = ['хуй', 'пизд', 'ебал', 'сука', 'блять', 'нахуй'];
        const isSpam = badWords.some(w => message.toLowerCase().includes(w)) || message.length < 2;
        
        // Если спам — шлем в ТГ и блокируем
        if (isSpam) {
            ctx.waitUntil(tgSend(env.ADMIN_BOT_TOKEN, `🚨 <b>Хакер/Спам:</b>\nIP: ${ip}\nID: ${sessionId}\n💬: ${message}`));
            return json({ reply: 'Я тебя вижу, хакер. Не балуйся.' });
        }

        if (!authHeader) {
            ctx.waitUntil(env.MESSAGES_KV.put(limitKey, (msgCount + 1).toString(), { expirationTtl: 86400 }));
        }

        const formattedHistory = (history || []).map(msg => ({
          role: msg.sender === 'user' ? 'user' : 'assistant',
          content: msg.text
        }));

        let reply = '';
        try {
            const aiResponse = await env.AI.run('@cf/meta/llama-3.1-8b-instruct', {
              messages: [
                { role: 'system', content: 'Ты — Доктор Брезель, добрый дедушка-сыровар. Отвечай кратко, вежливо.' },
                ...formattedHistory,
                { role: 'user', content: message }
              ]
            });
            reply = aiResponse.response || 'Ох, старый я стал. Давай еще раз.';
        } catch (e) {
            console.error('CF AI Error:', e);
            return json({ reply: "Ох, сеть барахлит. Подожди чуток." });
        }
        return json({ reply });;
      }

      // 5. ПОДДЕРЖКА (СВЯЗЬ С МЕНЕДЖЕРОМ)
      if (path === '/api/support' && request.method === 'POST') {
        const { message, sessionId, userEmail } = await request.json();
        
        const displayId = userEmail || sessionId;
        const text = `👤 <b>Клиент (${displayId})</b>\nID: ${sessionId}\n\n${message}\n\n<i>Свайпни это сообщение вправо, чтобы ответить.</i>`;
        
        ctx.waitUntil(tgSend(env.PANEL_BOT_TOKEN, text));
        return json({ success: true });
      }

      // 6. BREZEL'S GUARD SOS
      if (path === '/api/guard-help' && request.method === 'POST') {
        const { message, userId, userEmail } = await request.json();
        
        const displayId = userEmail || userId;
        ctx.waitUntil(tgSend(env.ADMIN_BOT_TOKEN, `🛡️ <b>SOS! Взлом аккаунта!</b>\nПочта: ${displayId}\nID: ${userId}\n💬: ${message}`));
        
        return json({ reply: 'Сигнал SOS отправлен. Проверьте почту для сброса пароля.' });
      }

      return json({ error: 'Not Found' }, 404);
    } catch (error) { return json({ error: error.message }, 500); }
  }
};